namespace CheckoutPricing.Domain;

public sealed class LoyaltyDiscountPolicy
{
    private const int MinimumSubtotalCents = 3_000;
    private const int LoyaltyCapCents = 2_000;

    public int Discount(int subtotalCents, LoyaltyTier tier, string? promoCode)
    {
        var loyaltyCents = LoyaltyPart(subtotalCents, tier);
        var promoCents = PromoCode.From(promoCode).Discount(subtotalCents - loyaltyCents);
        return Math.Min(subtotalCents, loyaltyCents + promoCents);
    }

    private static int LoyaltyPart(int subtotalCents, LoyaltyTier tier) =>
        subtotalCents < MinimumSubtotalCents
            ? 0
            : Math.Min(LoyaltyCapCents, subtotalCents * RatePercent(tier) / 100);

    private static int RatePercent(LoyaltyTier tier) => tier switch
    {
        LoyaltyTier.Bronze => 5,
        LoyaltyTier.Silver => 10,
        LoyaltyTier.Gold => 15,
        LoyaltyTier.Platinum => 20,
        _ => 0
    };
}
EOF
cat > src/CheckoutPricing.Domain/PromoCode.cs <<'EOF'
namespace CheckoutPricing.Domain;

public readonly record struct PromoCode
{
    private const int Welcome5Cents = 500;
    private const int Summer10Percent = 10;
    private const int Summer10CapCents = 1_500;

    private readonly string? code;

    private PromoCode(string? code) => this.code = code;

    public static PromoCode From(string? code) => new(code);

    public int Discount(int remainingCents)
    {
        if (Is("WELCOME5"))
        {
            return Welcome5Cents;
        }

        return Is("SUMMER10") ? Math.Min(Summer10CapCents, remainingCents * Summer10Percent / 100) : 0;
    }

    private bool Is(string name) => string.Equals(code, name, StringComparison.OrdinalIgnoreCase);
}
EOF
cat > src/CheckoutPricing.Domain/ShippingPolicy.cs <<'EOF'
namespace CheckoutPricing.Domain;

public sealed class ShippingPolicy
{
    private const int StandardFeeCents = 490;
    private const int FreeStandardFromCents = 5_000;
    private const int ExpressFeeCents = 990;

    public int Fee(int payableTotalCents, LoyaltyTier tier, bool express) =>
        express ? ExpressFee(tier) : StandardFee(payableTotalCents, tier);

    private static int ExpressFee(LoyaltyTier tier) => tier == LoyaltyTier.Platinum ? 0 : ExpressFeeCents;

    private static int StandardFee(int payableTotalCents, LoyaltyTier tier) =>
        tier is LoyaltyTier.Gold or LoyaltyTier.Platinum || payableTotalCents >= FreeStandardFromCents
            ? 0
            : StandardFeeCents;
}
EOF
